import { ObjectSchema } from "./utils/plugin-options-schema-joi-type"

interface ITestPluginOptionsSchemaReturnType {
  errors: Array<string>
  isValid: boolean
}

const validationOptions = {
  // Show all errors at once, rather than only the first one every time
  abortEarly: false,
}

export function testPluginOptionsSchema(
  pluginSchemaFunction: ({ Joi }: { Joi: any }) => ObjectSchema,
  pluginOptions: object
): ITestPluginOptionsSchemaReturnType {
  const pluginSchema = pluginSchemaFunction({ Joi })

  const errors: Array<string> = []

  // We only want to validate the fields that are present in the passed
  // options, so that plugin authors can test a partial set of options
  // without being required to provide every field the schema demands.
  Object.keys(pluginOptions).forEach(key => {
    let fieldSchema: ObjectSchema

    try {
      fieldSchema = pluginSchema.extract(key)
    } catch (e) {
      // The field isn't part of the schema, so there's nothing to validate
      // against — skip it.
      return
    }

    const { error } = fieldSchema.validate(
      (pluginOptions as Record<string, unknown>)[key],
      validationOptions
    )

    if (!error) {
      return
    }

    // Joi labels a bare value as "value", so we strip that placeholder out
    // and prefix the message with the actual field name. Array item errors
    // (labelled "[0]", "[1]", ...) are concatenated into a single entry.
    const message = error.details
      .map(detail => detail.message)
      .join(`. `)
      .replace(/"value" /g, ``)

    errors.push(`"${key}" ${message}`)
  })

  return {
    isValid: errors.length === 0,
    errors,
  }
}
